use std::{fs,path::Path};use serde_json::json;fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/early-x-sdk175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-early-x-sdk175");let p=d.join("README.md");let s=fs::read_to_string(&p).unwrap();let before="Every one of the 99 latency/profile captures finishes before its independent verification, decoding and raw-loss audit.";let after="All 99 latency/profile captures finish before any of their independent verifications, decoding or raw-loss audits.";assert_eq!(s.matches(before).count(),1);let s=s.replace(before,after).replace("Owner-user offline decoding avoids the earlier sudo/file-owner mismatch.","Offline decoding runs as the file owner after all captures.");fs::write(p,s).unwrap();fs::copy(r.join("publication.rs"),d.join("artifacts/publication.rs")).unwrap();fs::write(d.join("artifacts/publication-review.json"),serde_json::to_vec_pretty(&json!({"change":"clarify all-captures-before-verification boundary and remove irrelevant prior-decoder history","before":before,"after":after,"numbers_gates_scope_unchanged":true})).unwrap()).unwrap();}
